<?php function renderReceipt(array $s, array $items=[]): void { ?><section id="receipt" class="receipt bg-white text-black p-5 max-w-sm mx-auto font-mono text-xs"><div class="text-center border-b border-black pb-2"><strong class="text-base"><?=sanitize($_SESSION['club_name']??'CuePOS')?></strong><br>Thank you for visiting!</div><p>Date: <?=date('d/m/Y h:i A',strtotime($s['end_time']??'now'))?><br>Table: <?=sanitize($s['table_number']??'')?><br>Player: <?=sanitize($s['player_name']??$s['player_name_walkin']??'Walk-in Guest')?></p><hr><p>Table Time <span class="float-right"><?=money($s['table_amount']??0)?></span></p><?php foreach($items as $i): ?><p><?=sanitize($i['item_name'])?> × <?=intval($i['quantity'])?><span class="float-right"><?=money($i['subtotal'])?></span></p><?php endforeach; ?><hr><p>Discount <span class="float-right">-<?=money($s['discount_amount']??0)?></span></p><p class="font-bold text-sm">TOTAL <span class="float-right"><?=money($s['total_amount']??0)?></span></p><hr><p>Payment: <?=sanitize($s['payment_method']??'Cash')?><br>Points earned: +<?=intval($s['points_earned']??0)?></p></section><?php } ?>
<style>@media print{body *{visibility:hidden}.receipt,.receipt *{visibility:visible}.receipt{position:absolute;left:0;top:0;width:58mm;box-shadow:none}}</style>
